%[text] ## Introduction
%[text] In this project, the Healthy Dynamic PET (hedyPET) dataset containing \[F-18\]FDG dynamic PET/CT of 100 healthy humans was used (Hinge et al., 2026). The provided time-activity curves (TAC) as well as image-derived input function (IDIF) in this dataset were used to calculate the net-influx rate (Ki) for the brain through compartmental modeling. MATLAB was used for all data processing and analysis.
%[text] Dataset source: [https://doi.org/10.1038/s41597-026-08157-4](https://doi.org/10.1038/s41597-026-08157-4)
%%
%[text] ## Load pre-extracted data
%[text] The time activity curve (TAC) measurements for the brain, the image-derived arterial input function (AIF), and the Patlak Ki values provided in the dataset were already extracted in a previous project and are simply loaded here.
clearvars
load brainTACdata.mat;
load trueKi.mat;
load IDIF.mat;
%[text] The following are plots of the activity concentration versus time measurements for the brain and the ascending aorta (the AIF).
time_points = brainTACdata.("Frame Time Middle [s]");
brainCtrue = brainTACdata.("PET Mean [Bq/mL]"); %true activity concentration in brain
plot(time_points, brainCtrue, 'rx'); %[output:68e97df8]
title('Brain TAC') %[output:68e97df8]
xlabel('Time (min)') %[output:68e97df8]
ylabel('Activity (Bq/mL)') %[output:68e97df8]
aortaTAC = sub000IDIFdata.("PET Mean [Bq/mL]");
plot(time_points, aortaTAC,'x'); %[output:045d1b02]
xlabel('Time (min)') %[output:045d1b02]
ylabel('Activity (Bq/mL)') %[output:045d1b02]
title('Aorta TAC') %[output:045d1b02]
AIF = fit(time_points, sub000IDIFdata.("PET Mean [Bq/mL]"), 'pchipinterp'); %fit a piecewise function by interpolation
plot(time_points, feval(AIF, time_points)) %[output:23713984]
xlabel('Time (min)') %[output:23713984]
ylabel('Activity (Bq/mL)') %[output:23713984]
title('Aorta TAC (interpolated)') %[output:23713984]
%%
%[text] ## Estimating the net influx rate (Ki) by compartmental modeling.
%[text] The differential equations governing the kinetics of \[F-18\]FDG using the irreversible two-tissue compartment model are as follows:
%[text] $\\frac{{\\mathrm{d}\\mathrm{C}}\_1 \\left(t\\right)}{\\mathrm{d}\\mathrm{t}}=K\_1 A\\left(t\\right)-\\left(k\_2 +k\_3 \\right)C\_1 \\left(t\\right)${"editStyle":"visual"}
%[text] $\\frac{{\\mathrm{d}\\mathrm{C}}\_2 \\left(t\\right)}{\\mathrm{d}\\mathrm{t}}=k\_3 C\_1 \\left(t\\right)${"editStyle":"visual"}
%[text] The solution to this system of ODEs is:
%[text] $C\\left(t\\right)=\\frac{K\_{1\\;} }{k\_2 +k\_3 }\\left\\lbrack k\_3 +k\_2 e^{-\\left(k\_2 +k\_3 \\right)t} \\right\\rbrack \\otimes A\\left(t\\right)${"editStyle":"visual"}
%%
%[text] ## Representing the solution to the 2TCM in code
%[text] The concentration in tissue (C(t)) is approximated by trapezoidal integration instead of a convolution.
%Function to predict C at t = tau(end), the last element of the vector tau
function Cpred = predictC(k, tdata, AIF)
B = @(k, tau) k(1)/(k(2) + k(3)) * (k(3) + k(2) * exp(-(k(2) + k(3)) * (tau(end) - tau))); %tau(end) is a single time point for which C(t) will be evaluated while tau is a set of time points from 0 to tau(end)
A = @(tau) AIF(tau); %evaluate the interpolated AIF from tau = 0 to tau = t
BxA = @(k, tau) B(k, tau) .* A(tau); %multiply B with A at each point from tau = 0 to tau = t
areaBxA = @(k, tau) trapz(tau, BxA(k, tau)); %finds the area under the curve of BxA from tau = 0 to tau = t. tau should be a vector from time = 0 to time = t with each point corresponding to an element of tau

n = numel(tdata);
Cpred = zeros(n,1);

%loop through each element of xdata which should consist of the time points from 0 to t with each point corresponding to an element of time_points
for idx = 1:n
    tpoints = tdata(1:idx);
    tau = [0; tpoints];
    Cpred(idx) = areaBxA(k, tau);
end
end
%%
%[text] ## Estimating the kinetic parameters ($K\_1 ,k\_2 ,k\_3${"editStyle":"visual"}) and Ki by nonlinear curve fitting.
%[text] The code below attempts to estimate the values of k1, k2, and k3 by by minimizing the sum of squares between the predicted and true concentration values in tissue.
%Function to calculate the sum of squares between C predictions and true C
function weightedSS = fitSS(k, time_points, AIF, Ctrue)
    Cpred = predictC(k, time_points, AIF);
    squares = (Cpred - Ctrue).^2;
    weightedSS = sum(squares);
end

%Perform a search for the global minimum of the sum of squares for the brain predictions
brainOptProblem = createOptimProblem("fmincon",...
    objective=@(k) fitSS(k, time_points, AIF, brainCtrue),...
    x0 = rand(3,1) .* 0.1,...
    lb = [0; 0; 0], ...
    ub = [5; 5; 1], ...
    options = optimoptions(@fmincon, Algorithm="sqp",...
    Display = "off"));

gs = GlobalSearch( ...
    NumTrialPoints = 5000, ...
    NumStageOnePoints = 500);

[brainkEst, brainSS] = run(gs, brainOptProblem); %[output:70c0782e]
brainKi = (brainkEst(1) * brainkEst(3))/(brainkEst(2) + brainkEst(3)); %calculation of brain Ki using the microparameters K1, k2, and k3
%%
%[text] ## Validation of results
%[text] The values predicted by the 2TCM solution (Cpred) approximated using trapezoidal integration combined with the estimated kinetic parameters are plotted. The percent error between the calculated Ki and the "true" Ki provided in the dataset is calculated as well. 
brainCpredictions = predictC(brainkEst, time_points, AIF); %predicted activity concentration in brain;
plot(time_points, brainCpredictions, 'o'); %[output:3753224f]
xlabel('Time (min)') %[output:3753224f]
ylabel('Activity (Bq/mL)') %[output:3753224f]
hold on %[output:3753224f]
plot(time_points,brainCtrue,'r--'); %[output:3753224f]
hold off %[output:3753224f]
legend('Predicted C(t)', 'True C(t)'); %[output:3753224f]
title('Brain TAC') %[output:3753224f]
%%
brainError = (brainKi-truebrainKi)/truebrainKi*100;
brainresults = table(brainKi, truebrainKi, brainError, VariableNames=["Predicted Brain Ki" "True Brain Ki" "% error"]);
disp(brainresults); %[output:7f69899c]

